style.css:
@-moz-document domain("roblox.com") {
body {
    background-color: #f2f2f2 !important; /* Classic light gray background */
    font-family: Arial, sans-serif !important; /* Legacy font style */
  }

  .navbar, .header {
    background-color: #0072bc !important; /* Classic blue header */
    color: white !important;
    border-bottom: 2px solid #005a94 !important;
  }

  a {
    color: #005a94 !important; /* Classic blue links */
    text-decoration: none !important;
  }

  a:hover {
    text-decoration: underline !important;
  }

  .button, .btn {
    background-color: #0072bc !important;
    color: white !important;
    border: 1px solid #005a94 !important;
    border-radius: 4px !important;
    padding: 5px 10px !important;
  }

  .button:hover, .btn:hover {
    background-color: #005a94 !important;
  }

  .footer {
    background-color: #e2e2e2 !important;
    color: #333 !important;
    text-align: center !important;
    padding: 10px 0 !important;
  }
}
